formatted_regions = []
for d in districts:
    region_id = d["name"].lower().replace(" ", "_") + "_pk"
    formatted_regions.append({
        "id": region_id,
        "name": d["name"],
        "country": "Pakistan (" + d["province"] + ")",
        "climate_band": d["climate"],
        "lat": d["lat"],
        "lon": d["lon"],
        "soil_tendency": d["soil"],
        "crops_production": government_data.get(d["name"], {})
    })

with open("data/regions.json", "w") as f:
    json.dump(formatted_regions, f, indent=2)

print(f"Successfully generated regions.json with all {len(formatted_regions)} districts/cities in Pakistan.")
